"""Human-readable current rules, derived from the same profiles as the engine."""


def describe_profile(p):
    groups = []

    def group(title, rows):
        groups.append(
            {
                "title": title,
                "rules": [
                    dict(zip(("name", "value", "basis", "scope"), row)) for row in rows
                ],
            }
        )

    page = p["page"]
    group(
        "页面与版心",
        [
            (
                "纸张",
                f"{page['width_mm']} × {page['height_mm']} mm（A4）",
                "GB/T 9704 §5.1",
                "新文档和导入Word的纵向分节；横向分节保留",
            ),
            (
                "页边距",
                " / ".join(
                    f"{n}{page[k + '_mm']} mm"
                    for n, k in [
                        ("上", "top"),
                        ("下", "bottom"),
                        ("左", "left"),
                        ("右", "right"),
                    ]
                ),
                "GB/T 9704 §5.2.1；下/右边距由版心推算",
                "纵向页面",
            ),
            (
                "精确行字数",
                "不强制锁定22行28字，需在目标Office中复核",
                "工程边界；§5.2.3为一般要求",
                "全部输入",
            ),
        ],
    )
    rows = []
    for role, label in [
        ("title", "标题"),
        ("body", "正文"),
        ("heading1", "一级标题"),
        ("heading2", "二级标题"),
        ("heading3", "三级标题"),
        ("heading4", "四级标题"),
    ]:
        size = p["title_pt"] if role == "title" else p["body_pt"]
        rows.append(
            (
                label,
                f"{p['fonts'][role]} · {size} pt · 固定{p.get('title_line_pt', p['line_pt']) if role == 'title' else p['line_pt']} pt行距",
                "集团公司正式文件字体要求；字号与编排参考GB/T 9704-2012§5.2.2/7.3.3；固定行距为项目策略"
                if role == "body" and p["id"] == "official_body" and p["version"] in {"1.2.0", "1.3.0", "1.4.0"}
                else "公文正文参考§5.2.2/7.3.1/7.3.3；固定行距及专业报告字号为项目策略",
                "普通段落；含保护对象的段落保留",
            )
        )
    rows += [
        ("开头称谓／主送", "居左顶格，左缩进0、首行缩进0，无悬挂；字体行距沿用正文", "GB/T 9704-2012 §7.3.2；上下文保守识别，结构页可手动纠正", "Word和Markdown独立开头称谓或具体机关名称；不匹配正文引用、引出下文及礼仪用语"),
        ("机关署名／成文日期", "默认按盖章公文：文末日期右空四字，单一机关署名以日期为准居中；保持两段同页，长名称自然换行", "GB/T 9704-2012 §7.3.5.1；更多设置可关闭自动识别，独立规则letter_layout@1.0.0", "相邻独立单一机关名称及年月日；不生成印章，联合署名、合并段落及保护内容保留并提示；实际盖章和分页需Word/WPS复核"),
        ("段内换行", "手动换行结束的短行不拉伸字距，正文仍两端对齐", "Word兼容设置doNotExpandShiftReturn", "Markdown新生成文档"),
        ("Word双星号加粗", "同段成对**内非空且不超过50字符：转为加粗，移除四个定界星号，保留内部空白", "用户授权的标记解释规则，非国标强制要求", "DOC/DOCX普通正文与表格；复杂对象、代码、未配对及超长标记保留；SDK可关闭"),
        ("英文与数字", "标题及层级标题的英文、数字和编号随本级中文字体；正文默认方正仿宋简体，可选 Times New Roman"
         if p.get("latin_follow_roles") else "默认方正仿宋简体；更多设置可选 Times New Roman",
         "单位字体要求与用户选项，非国标强制西文字体", "含Markdown行内代码；独立代码块保留Consolas；保留的自动编号、保护对象及原表格字体需核对"),
        ("中文引号与括号", "默认将普通中文段落中成对的英文双引号、括号转为中文全角标点；可在更多设置中关闭", "集团正式文件中文标点口径；用户可选转换", "DOC、DOCX、Markdown；英文、未配对标点及保护内容保留"),
        (
            "段落间距",
            f"段前0 pt；标题段后{p['line_pt']} pt；正文及层级标题段后0 pt",
            "项目默认",
            "普通段落",
        ),
        (
            "缩进与对齐",
            "标题首行0、居中；正文和层级标题首行2字符、两端对齐",
            "正文缩进参考§7.3.3；其余为项目策略",
            "导入Word默认将支持的自动编号转固定文字并首行二字；关闭选项保留原编号缩进",
        ),
        (
            "标题分页",
            "文章标题与下段同页；导入Word中超过80字的层级段落允许跨页，短层级标题段内不分页；后接正文或下级标题时与下段同页，后接同级/上级标题或文末时允许分页",
            "项目默认",
            "普通标题段落",
        ),
        (
            "颜色与强调",
            "新文档黑色；保留Markdown强调；导入Word保留原颜色、上下标及行内强调",
            "§5.2.4与内容保护策略",
            "保护优先，不清洗具有含义的行内格式",
        ),
    ]
    if p.get('attachment_layout'):
        rows.append(('附件说明', '组前空一正文行；首行左空二字，续行及后续附件名称对齐首个名称',
                     '单位公文格式示范；参考GB/T 9704-2012 §7.3.4；规则attachment@1.0.0',
                     '文末明确的附件说明及从1起连续编号；不改原文字、编号，复杂对象与不明确组保留，结构页可人工纠正'))
    group("文字与段落", rows)
    table = p.get("table")
    group(
        "表格默认格式",
        [
            (
                "行距",
                f"{table['line_multiple']:g}倍（单倍行距）" if table else "固定20 pt",
                "项目默认，非国标强制数值",
                "新建表格及导入Word普通表格" if table else "仅Markdown新建表格",
            ),
            (
                "段前 / 段后",
                f"{table['space_before_pt']} pt / {table['space_after_pt']} pt"
                if table
                else "0 pt / 0 pt",
                "项目默认",
                "不使用空行撑开单元格",
            ),
            (
                "首行缩进",
                f"{table['first_line_chars']}字符" if table else "0字符",
                "项目默认",
                "普通表格",
            ),
            (
                "单元格留白",
                f"上/下各{table['cell_vertical_margin_mm']:g} mm；左右保留"
                if table
                else "沿用表格样式",
                "项目默认",
                "与段前段后分别控制",
            ),
            (
                "行高",
                "自动，取消固定行高" if table else "新建自动；导入保留",
                "项目默认",
                "避免多行文字、上下标被裁切",
            ),
            (
                "字体 / 字号",
                f"新建：{p['fonts']['body']} {p['table_pt']} pt；导入：保留原字体字号",
                "项目默认，非国标表内字号要求",
                "公文正文与专业报告可使用不同新建字号",
            ),
            (
                "对齐与结构",
                "新建：两端对齐、等宽列、网格线、首行重复表头；导入：保留对齐、列宽、边框、合并及表头设置",
                "项目默认 / 保护策略",
                "不重建原表格",
            ),
            (
                "保护例外",
                "目录域完整保护，正文排版后须在Word更新目录页码。导入Word：含修订、公式、图片/OLE、域、内容控件、嵌套表或编号的表格保留原格式",
                "保护策略",
                "仅处理正文顶层普通表格；页眉页脚中的表格保留",
            ),
        ],
    )
    group(
        "页码、列表与其他内容",
        [
            (
                "页码",
                "默认开启，可关闭新增；宋体14 pt，PAGE域，两侧一字线，奇页右/偶页左空一字",
                "参考GB/T 9704 §7.5",
                "导入Word无页脚时新增；已有页脚完整保留并提示核对，复杂分节或受影响页眉不自动处理",
            ),
            (
                "页眉 / 页脚距边界",
                f"新建：{page.get('header_mm', 15)} mm / {page.get('footer_mm', 22)} mm",
                "单位公文格式示范" if 'footer_mm' in page else "项目默认",
                "导入Word纵向页脚设25 mm，页眉与横向分节保留" if 'footer_mm' in page else "导入Word保留原距离",
            ),
            (
                "列表",
                "按Markdown原文写入文字序号/项目符号，不自动续号；顶层有序段落左缩进0、首行2字符、回行顶格；嵌套及无序列表保留层级缩进；沿用正文固定行距",
                "项目默认",
                "导入Word默认按原起始值/重启语义固定序号；复杂编号整组保留并提示，可关闭转换",
            ),
            (
                "引用 / 代码 / 分隔线",
                "引用沿用正文；代码段沿用正文，行内代码Consolas；分隔线灰色0.5 pt",
                "Markdown映射策略",
                "不自动将公式文本转换成OMML",
            ),
            (
                "图片",
                "仅使用提供的PNG/JPEG；正文宽度上限150 mm、表内130 mm；每图不超过4000万像素",
                "项目策略",
                "不自动联网抓取图片；导入Word图片对象保留",
            ),
        ],
    )
    group(
        "内容保护与适用边界",
        [
            (
                "源文内容",
                "不改写日期、金额、单位、引用；不接受全部修订；不删除批注或嵌入对象",
                "内容保护",
                "所有入口",
            ),
            (
                "DOC转换",
                "保留DOC原件、兼容转换基线及规范版；转换后的DOCX按相同保护规则处理",
                "兼容转换",
                "不宣称任意DOC跨格式无损",
            ),
            (
                "未覆盖",
                "；".join(p["not_covered"]),
                "范围边界",
                "公文正文模板不等同完整发文合规",
            ),
        ],
    )
    return groups
